  "test_path": "tests/unit/test_observe_input_transform.py",
  "test": "import json
from typing import Any

from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes


def test_input_transform_applied(langfuse_memory_client: Any, memory_exporter: Any) -> None:
    @observe(
        name="custom_input",
        input_transform=lambda d: {"combined": f"{d['x']}_{d['y']}"},
    )
    def func(x, y):
        return "done"

    func(5, 10)

    langfuse_memory_client.flush()
    spans = [s for s in memory_exporter.get_finished_spans() if s.name == "custom_input"]
    assert spans, "Span not recorded"
    span = spans[0]
    attributes = span.attributes
    assert LangfuseOtelSpanAttributes.OBSERVATION_INPUT in attributes
    observed_input = json.loads(attributes[LangfuseOtelSpanAttributes.OBSERVATION_INPUT])
    assert observed_input == {"combined": "5_10"}
